create or replace function public.admin_conversion_dashboard(range_days integer default 30) returns jsonb language plpgsql stable security definer set search_path = '' as $$ declare bounded_days integer := greatest(7, least(coalesce(range_days, 30), 90)); result jsonb; begin if auth.uid() is null or not private.has_role('admin'::public.user_role) then raise exception 'Admin access required'; end if; with cohort as (select auth_user.id, auth_user.created_at, auth_user.email_confirmed_at, case when auth_user.raw_user_meta_data ->> 'signup_intent' in ('account','follow','score_report','pickem') then auth_user.raw_user_meta_data ->> 'signup_intent' else 'unknown' end signup_intent, case when auth_user.raw_user_meta_data ->> 'signup_source' in ('home','scoreboard') then auth_user.raw_user_meta_data ->> 'signup_source' else 'direct_or_other' end signup_source, exists(select 1 from public.member_account_status s where s.user_id=auth_user.id and s.status='active') is_active, exists(select 1 from public.pickem_picks p where p.user_id=auth_user.id) has_pick from auth.users auth_user where auth_user.created_at >= now() - make_interval(days => bounded_days)) select jsonb_build_object('generated_at',now(),'range_days',bounded_days,'summary',jsonb_build_object('total_members',(select count(*) from auth.users),'new_accounts',count(*),'confirmed_accounts',count(*) filter(where email_confirmed_at is not null),'active_accounts',count(*) filter(where is_active),'pickem_participants',count(*) filter(where has_pick),'complete_slate_members',0)) into result from cohort; return result; end; $$;
